let collector='',collectorToken='',collectorTimer=null,collectorBusy=false;
window.collectorAuth=url=>collector&&url.origin===new URL(collector).origin?{Authorization:'Bearer '+collectorToken}:{};
function plan(){return {time:$('#schedule-time').value,timezone:'Asia/Kolkata',routes:routes.map(r=>r.id),horizons}}
function basket(){const day=today();$('#collection-basket').innerHTML='<div class="basket-routes">'+routes.map(r=>'<span>'+esc(r.id.replace('-',' → '))+'</span>').join('')+'</div><div class="date-basket">'+horizons.map(h=>`<div><b>T+${h}</b><span>${dateLabel(plusDate(day,h))}</span></div>`).join('')+'</div><div class="basket-total"><strong>30</strong><span>route-and-date searches per adapter per run</span></div>'}
async function service(path,body){if(!collector)throw Error('Connect your collection service first.');const res=await fetch(collector+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+collectorToken,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000),credentials:'omit'});const data=await res.json();if(!res.ok)throw Error(data.error||'Service request failed.');return data}
function showStatus(s){$('#automation-state').textContent=(s.mode==='demo'?'Demo collector':'Live adapter')+' · '+(s.running?'Collecting':s.schedule.enabled?'Daily schedule enabled':'Schedule paused');$('#run-summary').textContent=s.schedule.enabled?'Daily at '+s.schedule.time+' IST · '+(s.mode==='demo'?'Simulated fares only':'Configured adapter'):'Schedule paused';$('#schedule-time').value=s.schedule.time;$('#run-history').innerHTML=s.runs.length?s.runs.map(r=>`<tr><td>${esc(new Date(r.started).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</td><td>${esc(r.mode)}</td><td><span class="valid">${esc(r.status)}</span></td><td>${r.count}</td><td>${esc(r.detail)}</td></tr>`).join(''):'<tr><td colspan="5">No runs yet. Use Run collection to collect your first basket.</td></tr>';$('#run-collection').disabled=s.running;$('#service-message').textContent='Connected · '+(s.mode==='demo'?'Demo mode; fares are simulated.':'Live adapter configured; check run results for coverage.');}
async function syncCollector(){if(collectorBusy||!collector)return;collectorBusy=true;try{showStatus(await service('/status'));if(api===collector+'/observations'){try{await load(api)}catch(e){$('#service-message').textContent=e.message}}}catch(e){$('#automation-state').textContent='Service unavailable';$('#service-message').textContent=e.message}finally{collectorBusy=false}}
function polling(){clearInterval(collectorTimer);const seconds=Number($('#poll-interval').value);if(seconds&&collector)collectorTimer=setInterval(syncCollector,seconds*1000)}
$('#connect-service').onclick=async()=>{const b=$('#connect-service');b.disabled=true;try{const u=new URL($('#service-url').value.trim());if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw Error('Enter an HTTPS service URL without credentials or query parameters.');if(!$('#service-token').value.trim())throw Error('Enter the service access token.');collector=u.href.replace(/\/$/,'');collectorToken=$('#service-token').value.trim();showStatus(await service('/status'));api=collector+'/observations';requestId++;observations=[];live=false;refreshSources();render();try{await load(api)}catch(e){$('#service-message').textContent='Connected. '+e.message}polling();toast('Collection service connected.')}catch(e){collector='';collectorToken='';$('#service-message').textContent=e.message}finally{b.disabled=false}};
$('#save-schedule').onclick=async()=>{try{const data=await service('/schedule',{...plan(),enabled:true});showStatus(data);$('#schedule-note').textContent='Daily collection enabled at '+data.schedule.time+' IST. The service must remain running.';toast('Daily schedule saved on your collector.')}catch(e){toast(e.message)}};
$('#run-collection').onclick=async()=>{const b=$('#run-collection');b.disabled=true;try{const result=await service('/run',plan());showStatus(result);toast('Collection started. Run history will update.');setTimeout(syncCollector,2000)}catch(e){toast(e.message)}finally{b.disabled=false}};
$('#poll-interval').onchange=polling;
const oldView=view;view=function(name){oldView(name);if(name==='automation'){basket();if(collector)syncCollector()}};
basket();

$('#pause-schedule').onclick=async()=>{try{showStatus(await service('/schedule',{...plan(),enabled:false}));$('#schedule-note').textContent='Daily schedule paused. An active run will finish.';toast('Daily schedule paused.')}catch(e){toast(e.message)}};
